document.addEventListener("DOMContentLoaded",()=>{const e=document,t=e.querySelector("#mspress-reset-scope"),s=e.querySelector("[data-mspress-reset-plugins]");if(t&&s){const e=s.querySelectorAll('input[name="plugins[]"]'),r=()=>{const r="plugins"===t.value;s.hidden=!r,e.forEach(e=>{e.disabled=!r})};t.addEventListener("change",r),r()}e.querySelectorAll(".mspress-editor-form").forEach(e=>{e.addEventListener("submit",()=>{const t=e.querySelector('[type="submit"]');t&&(t.disabled=!0)})})});